// scripts/generate-regional-library.js
// Genere la 1ere vague regionale (46 condition) + symptomes locaux + questions de triage.
// Securite: relancer le script echoue volontairement si les donnees existent deja (pas de doublon).
const fs = require('fs');
const path = require('path');
const root = path.resolve(__dirname, '..');
const R = (p) => path.join(root, p);
const L = (ar, en, fr) => ({ ar, en, fr });
const S = (title, url) => ({ title, url });
const ICD = S('ICD-10-CM (WHO/CDC)', 'https://www.cdc.gov/nchs/icd/icd-10-cm.htm');
const WHO = S('WHO - ICD-10 International Classification of Diseases', 'https://icd.who.int/browse10/2019/en');
const CDC = S('CDC - Centers for Disease Control and Prevention', 'https://www.cdc.gov/');
const MLP = (p) => S('MedlinePlus (NLM) - ' + p, 'https://medlineplus.gov/' + p);
const read = (p) => JSON.parse(fs.readFileSync(R(p), 'utf8'));
const write = (p, o) => { fs.mkdirSync(path.dirname(R(p)), { recursive: true }); fs.writeFileSync(R(p), JSON.stringify(o, null, 2) + '\n'); console.log('wrote ' + p); };
const TODAY = '2026-09-26';

/* حماية: يمنع التوليد المزدوج الذي يُنشئ تكرارًا في السجلات. */
if (fs.existsSync(path.join(root, 'data/medical/regionalConditions.json'))) {
  console.error('regionalConditions.json already exists - refusing to regenerate (delete it manually if you intend to rebuild).');
  process.exit(1);
}

