const symDoc = read('data/medical/symptoms.json');
// fever (HP:0001945) is systemic: add head_neck so head/neck conditions may reference it
for (const s of symDoc.symptoms) {
  if (s.id === 'hpo:0001945' && !s.regions.includes('head_neck')) s.regions.push('head_neck');
  if (s.hpo && !s.ontologyStatus) s.ontologyStatus = 'standard';
}
for (const [id, ar, en, fr, dAr, dEn, dFr, regions, redFlag] of NEW_SYMPTOMS) {
  if (symDoc.symptoms.some((s) => s.id === id)) throw new Error('duplicate symptom ' + id);
  symDoc.symptoms.push({
    id, hpo: null, ontologyStatus: 'local',
    name: L(ar, en, fr),
    description: L(dAr, dEn, dFr),
    regions, redFlag,
    ontologyNote: L(
      'مصطلح محلي داخل التطبيق بانتظار الربط بكود HPO/SNOMED مُتحقَّق منه؛ لم يُختَرَع كود.',
      'Local in-app term, pending verified HPO/SNOMED mapping; no code was invented.',
      'Terme local de l application, en attente d une correspondance HPO/SNOMED vérifiée.')
  });
}
symDoc.schemaVersion = '1.1.0';
symDoc.generatedFrom = [
  'Human Phenotype Ontology (HPO) - open, https://hpo.jax.org/',
  'BodyMap Pain local clinical terms (ontology mapping pending)'
];
symDoc.notice = 'أعراض مرجعية عامة للتعليم فقط. الأعراض المعنونة بـ hpo تعتمد كودًا معياريًا، والأعراض المصنّفة ontologyStatus=local هي مصطلحات داخل التطبيق بانتظار ربط موثّق بكود HPO/SNOMED ولم يُختَرع لها أي كود. ليست تشخيصًا ولا بديلًا عن الطبيب المؤهل.';
write('data/medical/symptoms.json', symDoc);

